const out = phi.js(() => {
  const items = [...document.querySelectorAll('h1,h2,h3,h4,button,[role="tab"],[class*="accordion"],[class*="faq"]')].slice(0,120).map(e => ({
    tag: e.tagName,
    cls: (e.className||"").toString().slice(0,50),
    txt: (e.innerText||"").trim().slice(0,90)
  })).filter(x => x.txt);
  const bodyLen = document.body.innerText.length;
  return { items, bodyLen, url: location.href };
});
