const out = phi.js(() => {
  const h4s = [...document.querySelectorAll('h4.card-title')];
  const target = h4s.find(h => /lost an item/i.test(h.innerText));
  if (!target) return { found: false };
  const card = target.closest('.block.faq');
  const heading = card.querySelector('.card-heading');
  return {
    found: true,
    cardHTMLstart: card.outerHTML.slice(0, 1200),
    headingAria: heading.getAttribute('aria-expanded'),
    id: target.id || '',
    parentId: card.id || '',
    collapsedClass: card.className,
    bodyText: (card.innerText || '').slice(0, 500)
  };
});
return out;

const a = phi.query('a[data-gtm-label="What do I do if I lost an item on the bus?"]', { limit: 1 });
if (a.items.length) { phi.click('a[data-gtm-label="What do I do if I lost an item on the bus?"]'); }
phi.waitForElement('.card-collapse.collapse.show, .card-collapse.show', 4000);
const out = phi.js(() => {
  const els = [...document.querySelectorAll('[role="tabcard"], .card-collapse')].filter(e => /lost and found|lost item/i.test(e.innerText||''));
  return els.map(e => ({ cls: e.className, shown: e.classList.contains('show'), text: (e.innerText||'').trim() }));
});
return { clicked: a.total, open: out };

phi.keep("lostitem_faq", {
  question: "What do I do if I lost an item on the bus?",
  answer: "If an item is lost on a bus, a lost item inquiry must be reported to our lost and found department by filling out this form (/contact-us). Once you've submitted the necessary information on the lost item, it will be entered into our system for processing by our lost and found department. Our lost and found department responds to all loss inquiries. The time frame of response may take several days as an investigation to find the lost item must be completed. Megabus makes every attempt to return lost items to their rightful owners and will assist with retrieval to the best of our ability.",
  page: "https://us.megabus.com/help"
});
const t = phi.tabs.open("https://us.megabus.com/contact-us");
return t;

const links = phi.query("a", { fields: ["href", "text"], limit: 60 });
const iframes = phi.query("iframe", { fields: ["src"], limit: 20 });
const forms = phi.query("form", { fields: ["action", "id"], limit: 10 });
return { links: links.items.filter(l => l.href), iframes, forms };

phi.narrate("Checking the help page for the lost-and-found form itself");
phi.goto("https://us.megabus.com/help");
phi.waitForNetworkIdle({ timeoutMs: 8000 });
const t = phi.text();
const idx = t.toLowerCase().indexOf("lost");
const links = phi.query("a", { fields: ["href", "text"], limit: 120 });
return {
  around: t.slice(Math.max(0, idx - 300), idx + 1500),
  lostLinks: links.items.filter(l => /lost|found/i.test((l.text || "") + (l.href || "")))
};

const obs = phi.observe({ maxElements: 60 });
const links = phi.query("a", { fields: ["href", "text"], limit: 120 });
return {
  nodes: obs.nodes.slice(0, 40),
  total: obs.total,
  links: links.items.filter(l => /contact|found|lost|form|chat|email/i.test((l.text||"") + (l.href||""))),
  iframes: phi.query("iframe", { fields: ["src"], limit: 20 }).items
};

const faq = phi.recall("lostitem_faq");
phi.narrate("Pulling up the lost-item answer I already found");
return faq;

phi.goto("https://us.megabus.com/help");
phi.waitForNetworkIdle({ timeoutMs: 8000 });
// find the lost item FAQ entry and the link inside its answer
const info = phi.js(() => {
  const out = [];
  const els = Array.from(document.querySelectorAll('a'));
  for (const a of els) {
    const t = (a.textContent || '').trim();
    if (/this form|lost and found|lost item|lost & found/i.test(t)) {
      out.push({ text: t, href: a.href });
    }
  }
  return out;
});
const links = phi.query("a", { fields: ["href", "text"], limit: 200 });
return { js: info, matches: links.items.filter(l => /lost|found|form|contact/i.test((l.text||"")+(l.href||""))) };

phi.goto("https://us.megabus.com/contact-us");
phi.waitForNetworkIdle({ timeoutMs: 8000 });
const txt = phi.text();
const forms = phi.query("form", { limit: 10 });
const inputs = phi.query("input, textarea, select", { fields: ["type", "name", "placeholder", "id"], limit: 40 });
const btns = phi.query("button, a[role=button]", { fields: ["text"], limit: 40 });
const headings = phi.query("h1, h2, h3, h4", { fields: ["text"], limit: 40 });
return { text: txt.slice(0, 4000), forms: forms.total, inputs: inputs.items, btns: btns.items, headings: headings.items };

phi.narrate("Checking whether the contact page really has a lost-item form behind its chat widget");
const info = phi.js(() => {
  const frames = Array.from(document.querySelectorAll('iframe')).map(f => ({src: f.src, id: f.id, title: f.title, w: f.clientWidth, h: f.clientHeight}));
  const scripts = Array.from(document.querySelectorAll('script[src]')).map(s => s.src).filter(s => /chuck|chat|zendesk|livechat|intercom|form|podium|gladly|kustomer/i.test(s));
  const anyChuck = Array.from(document.querySelectorAll('[id],[class]')).map(e => e.id || e.className).filter(v => typeof v === 'string' && /chuck|chat|lost|found/i.test(v)).slice(0, 40);
  return { frames, scripts, anyChuck };
});
const links = phi.query("a", { fields: ["href", "text"], limit: 100 });
return { info, links: links.items.filter(l => l.href && !/^https:\/\/us\.megabus\.com\/#/.test(l.href)) };

phi.narrate("Checking the chat page the contact page points to");
const a = phi.goto("https://us.megabus.com/webchat");
phi.waitForNetworkIdle({ timeoutMs: 8000 });
const t = phi.text().slice(0, 2500);
const forms = phi.query("form").total;
const frames = phi.js(() => Array.from(document.querySelectorAll('iframe')).map(f => ({src: f.src, title: f.title, h: f.clientHeight, w: f.clientWidth})));
const inputs = phi.query("input, textarea, select", { fields: ["type","name","placeholder"], limit: 30 });
