return { title: a.title, url: a.url, text: t, forms, frames, inputs: inputs.items, heads: heads.items };

phi.narrate("Back on the help page to read the lost-item answer on screen one more time");
phi.goto("https://us.megabus.com/help");
phi.waitForNetworkIdle({ timeoutMs: 8000 });
const obs = phi.observe({ maxElements: 200 });
const searchNode = obs.nodes.find(n => /search/i.test(n.role + " " + (n.name || "") + " " + (n.text || "")));
const items = obs.nodes.filter(n => /lost/i.test((n.text || "") + " " + (n.name || ""))).slice(0, 10);
return { url: obs.url, searchNode, items };

phi.narrate("Opening the lost-item question on the help page to read the answer as it shows on screen");
phi.goto("https://us.megabus.com/help");
phi.waitForNetworkIdle({ timeoutMs: 8000 });
const obs = phi.observe({ maxElements: 250 });
const tab = obs.nodes.find(n => n.role === "tab" && /lost an item/i.test(n.name || ""));
let clicked = null, after = null;
if (tab) {
  clicked = phi.click(tab.ref);
  phi.sleep(800);
  const t = phi.text();
  const i = t.toLowerCase().indexOf("lost an item");
  after = i >= 0 ? t.slice(i, i + 1200) : t.slice(0, 1200);
}
const links = phi.query("a", { fields: ["href", "text"], limit: 200 }).items.filter(l => l.href && /contact|lost|found|webchat|mailto/i.test(l.href + " " + (l.text || "")));
return { clicked: clicked && { changed: clicked.changed, url: clicked.url }, after, links };
